import sys

def solve():
    # Read all tokens from standard input quickly
    data = sys.stdin.buffer.read().split()
    if not data:
        return
    N = int(data[0])
    P = [int(x) for x in data[1:1+N]]

    # Store the original 1-based position of each value in P
    pos_orig = [0] * (N + 1)
    for i, x in enumerate(P, 1):
        pos_orig[x] = i

    # Fenwick tree (1-indexed) initialized in O(N)
    bit = [0] * (N + 2)
    for i in range(1, N + 1):
        bit[i] += 1
        nxt = i + (i & -i)
        if nxt <= N:
            bit[nxt] += bit[i]

    total = 0
    # Process elements from N down to 1
    for v in range(N, 0, -1):
        idx = pos_orig[v]

        # Inline BIT query to get current relative position of `v`
        s = 0
        curr = idx
        while curr > 0:
            s += bit[curr]
            curr -= curr & -curr
        p = s

        # If `v` needs to be shifted to the right among the remaining active elements
        if p < v:
            # The swaps will occur at positions p, p+1, ..., v-1
            total += (p + v - 1) * (v - p) // 2

        # Inline BIT update to remove `v` from the active elements prefix
        curr = idx
        while curr <= N:
            bit[curr] -= 1
            curr += curr & -curr

    print(total)

if __name__ == '__main__':
    solve()
